generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (COALESCE(?invCount, 0) AS ?profileCount) (COALESCE(?holdCount, 0) AS ?holdingCount)
WHERE {
  {
    SELECT DISTINCT ?category WHERE {
      { ?inv a wm:Investor ; wm:category ?category . }
      UNION
      { ?hold a wm:PortfolioHolding ; wm:category ?category . }
    }
  }
  OPTIONAL {
    SELECT (COUNT(DISTINCT ?inv) AS ?invCount) WHERE {
      ?inv a wm:Investor ; wm:category ?category .
    }
  }
  OPTIONAL {
    SELECT (COUNT(DISTINCT ?hold) AS ?holdCount) WHERE {
      ?hold a wm:PortfolioHolding ; wm:category ?category .
    }
  }
}
ORDER BY ?category

generate.final_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (SUM(?invFlag) AS ?profileCount) (SUM(?holdFlag) AS ?holdingCount)
WHERE {
  {
    SELECT ?category ?invFlag ?holdFlag WHERE {
      {
        ?inv a wm:Investor ; wm:category ?category .
        BIND(1 AS ?invFlag) BIND(0 AS ?holdFlag)
      }
      UNION
      {
        ?hold a wm:PortfolioHolding ; wm:category ?category .
        BIND(0 AS ?invFlag) BIND(1 AS ?holdFlag)
      }
    }
  }
}
GROUP BY ?category
ORDER BY ?category

